class RedirectCookieAdapter(CookieRecordingAdapter):
    def __init__(self, routes):
        self.routes = routes

    def send(self, request, **kwargs):
        response = super(RedirectCookieAdapter, self).send(request, **kwargs)
        location, cookies = self.routes.get(request.url, (None, []))
        response.raw = CookieResponseRaw(cookies)
        if location:
            response.status_code = 302
            response.headers["Location"] = location
        return response


