    cookielib.LWPCookieJar, RequestsCookieJar,
])
@pytest.mark.parametrize("redirect", [False, True])
def test_request_cookies_are_isolated(jar_class, redirect):
    values = {"token": "request", "temporary": "one"}
    cookies = values.copy() if jar_class is dict else jar_class()
    if jar_class is not dict:
        for name, value in values.items():
            cookies.set_cookie(create_cookie(name, value))
    routes = {
        "https://example.test/start": ("https://example.test/middle", []),
        "https://example.test/middle": ("https://example.test/end", []),
    } if redirect else {}
    with requests.Session() as session:
        session.trust_env = False
        session.mount("https://", RedirectCookieAdapter(routes))
        session.cookies["token"] = "session"
        session.cookies["default"] = "kept"
        response = session.get("https://example.test/start", cookies=cookies)
        assert len(response.history) == (2 if redirect else 0)
        for hop in response.history + [response]:
            assert set(hop.request.headers["Cookie"].split("; ")) == {
                "token=request", "temporary=one", "default=kept"}
        assert session.cookies.get_dict() == {"token": "session", "default": "kept"}
