])
def test_redirect_reapplies_cookie_scope(outside):
    start = "https://example.test/private/start"
    end = "https://example.test/private/end"
    cookies = cookielib.MozillaCookieJar()
    cookies.set_cookie(create_cookie("token", "request", domain="example.test",
